content:
:root {
  --primary-color: #3b82f6;
  --primary-hover: #2563eb;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-color: #1e293b;
  --text-secondary: #64748b;
  --border-color: #e2e8f0;
  --radius: 12px;
}

body {
  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-color);
  -webkit-font-smoothing: antialiased;
}

.app-container {
  max-width: 800px;
  margin: 0 auto;
  padding: 20px;
  box-sizing: border-box;
}

.header {
  text-align: center;
  margin-bottom: 24px;
}

.title {
  font-size: 1.8rem;
  font-weight: 700;
  color: var(--text-color);
  margin: 0;
}

.main-content {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.card {
  background: var(--card-bg);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  box-sizing: border-box;
}

.form-group {
  margin-bottom: 16px;
}

.label {
  display: block;
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: 6px;
  color: var(--text-color);
}

.input {
  width: 100%;
  padding: 10px 12px;
  font-size: 1rem;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  box-sizing: border-box;
  outline: none;
  transition: border-color 0.2s;
}

.input:focus {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
}

.btn {
  display: inline-block;
  width: 100%;
  padding: 12px;
  font-size: 1rem;
  font-weight: 600;
  text-align: center;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.2s;
  box-sizing: border-box;
}

.btn-primary {
  background-color: var(--primary-color);
  color: #ffffff;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.result-section {
  margin-top: 20px;
  padding: 16px;
  background-color: #eff6ff;
  border-radius: 8px;
  text-align: center;
}

.bmi-value {
  font-size: 2rem;
  font-weight: 700;
  color: var(--primary-color);
  margin-bottom: 4px;
}

.bmi-judgment {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--text-color);
}

.chart-section {
  margin-top: 20px;
}

.history-section {
  margin-top: 20px;
}

.history-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px;
  border-bottom: 1px solid var(--border-color);
  font-size: 0.95rem;
}

.history-item:last-child {
  border-bottom: none;
}

@media (min-width: 640px) {
  .app-container {
    padding: 40px 20px;
  }
}

export interface BmiRecord {
  id: string;
  height: number;
  weight: number;
  bmi: number;
  judgment: string;
  date: string;
}

import { ResponsiveContainer, LineChart, Line, XAxis, YAxis, Tooltip, CartesianGrid } from 'recharts';
import { BmiRecord } from './types';

interface BmiChartProps {
  records?: BmiRecord[];
}

export default function BmiChart({ records = [] }: BmiChartProps) {
  const safeRecords = Array.isArray(records) ? records : [];

  if (safeRecords.length === 0) {
    return null;
  }

  const chartData = safeRecords.map((record) => ({
    date: record.date,
    bmi: record.bmi,
    weight: record.weight,
  }));

  return (
    <div className="chart-section card">
      <h3 style={{ marginTop: 0, marginBottom: '16px', fontSize: '1.1rem', color: 'var(--text-color)' }}>
        BMI推移グラフ
      </h3>
      <div style={{ width: '100%', height: 250 }}>
        <ResponsiveContainer>
          <LineChart data={chartData} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
            <XAxis dataKey="date" stroke="#64748b" fontSize={12} />
            <YAxis stroke="#64748b" fontSize={12} domain={['dataMin - 1', 'dataMax + 1']} />
            <Tooltip />
            <Line
              type="monotone"
              dataKey="bmi"
              stroke="#3b82f6"
              strokeWidth={3}
              dot={{ r: 4, fill: '#3b82f6' }}
              activeDot={{ r: 6 }}
              name="BMI"
            />
          </LineChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { BmiRecord } from './types';
import BmiChart from './BmiChart';

export default function App() {
  const [height, setHeight] = useState<string>('');
  const [weight, setWeight] = useState<string>('');
  const [records, setRecords] = useState<BmiRecord[]>(() => {
    const saved = localStorage.getItem('bmi_records');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed)) {
          return parsed;
        }
      } catch {
        return [];
      }
    }
    return [
      {
        id: '1',
        height: 170,
        weight: 65,
        bmi: 22.5,
        judgment: '標準体重',
        date: '2023-10-01',
      },
    ];
  });

  const [latestResult, setLatestResult] = useState<{ bmi: number; judgment: string } | null>(null);

  useEffect(() => {
    localStorage.setItem('bmi_records', JSON.stringify(records));
  }, [records]);

  const getJudgment = (bmi: number): string => {
    if (bmi < 18.5) return '低体重 (やせ)';
    if (bmi < 25) return '標準体重';
    if (bmi < 30) return '肥満 (1度)';
    if (bmi < 35) return '肥満 (2度)';
    if (bmi < 40) return '肥満 (3度)';
    return '肥満 (4度)';
  };

  const handleCalculate = (e: React.FormEvent) => {
    e.preventDefault();
    const h = parseFloat(height);
    const w = parseFloat(weight);

    if (!h || !w || h <= 0 || w <= 0) {
      return;
    }

    const heightInMeters = h / 100;
    const bmiValue = parseFloat((w / (heightInMeters * heightInMeters)).toFixed(1));
    const judgmentText = getJudgment(bmiValue);

    setLatestResult({ bmi: bmiValue, judgment: judgmentText });

    const newRecord: BmiRecord = {
      id: Date.now().toString(),
      height: h,
      weight: w,
      bmi: bmiValue,
      judgment: judgmentText,
      date: new Date().toISOString().split('T')[0],
    };

    const currentRecords = Array.isArray(records) ? records : [];
    setRecords([newRecord, ...currentRecords]);
    setHeight('');
    setWeight('');
  };

  const safeRecords = Array.isArray(records) ? records : [];

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">BMI計算・管理ツール</h1>
      </header>

      <main className="main-content">
        <div className="card">
          <form onSubmit={handleCalculate}>
            <div className="form-group">
              <label className="label">身長 (cm)</label>
              <input
                type="number"
                step="0.1"
                className="input"
                placeholder="例: 170"
                value={height}
                onChange={(e) => setHeight(e.target.value)}
                required
              />
            </div>
            <div className="form-group">
              <label className="label">体重 (kg)</label>
              <input
                type="number"
                step="0.1"
                className="input"
                placeholder="例: 65"
                value={weight}
                onChange={(e) => setWeight(e.target.value)}
                required
              />
            </div>
            <button type="submit" className="btn btn-primary">
              計算して記録する
            </button>
          </form>

          {latestResult && (
            <div className="result-section">
              <div className="bmi-value">{latestResult.bmi}</div>
              <div className="bmi-judgment">{latestResult.judgment}</div>
            </div>
          )}
        </div>

        <BmiChart records={safeRecords} />

        <div className="card history-section">
          <h3 style={{ marginTop: 0, marginBottom: '16px', fontSize: '1.1rem', color: 'var(--text-color)' }}>
            計測履歴
          </h3>
          {safeRecords.length === 0 ? (
            <p style={{ color: 'var(--text-secondary)', textAlign: 'center', margin: 0 }}>履歴がありません</p>
          ) : (
            <div>
              {safeRecords.map((record) => (
                <div key={record.id} className="history-item">
                  <div>
                    <strong>{record.date}</strong>
                    <div style={{ fontSize: '0.85rem', color: 'var(--text-secondary)' }}>
                      身長: {record.height}cm / 体重: {record.weight}kg
                    </div>
                  </div>
                  <div style={{ textAlign: 'right' }}>
                    <div style={{ fontWeight: '700', color: 'var(--primary-color)' }}>BMI: {record.bmi}</div>
                    <div style={{ fontSize: '0.85rem', color: 'var(--text-secondary)' }}>{record.judgment}</div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </main>
    </div>
  );
}
